package com.pousadamareaita.http;

import com.pousadamareaita.exception.ReservationException;
import com.pousadamareaita.model.RatePlan;
import com.pousadamareaita.model.Reservation;
import com.pousadamareaita.model.Room;
import com.pousadamareaita.service.ReservationService;
import com.pousadamareaita.storage.RoomRepository;
import com.google.gson.JsonObject;
import com.google.gson.JsonElement;
import io.javalin.Javalin;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;

public class ReservationController {
    private final ReservationService reservationService;
    private final RoomRepository roomRepository;
    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM-dd");

    public ReservationController(ReservationService reservationService) {
        this.reservationService = reservationService;
        this.roomRepository = new RoomRepository();
    }

    public void registerRoutes(Javalin app) {
        app.post("/reservations", this::createReservation);
        app.get("/reservations/{id}", this::getReservation);
        app.post("/reservations/{id}/confirmation", this::confirmReservation);
        app.post("/reservations/{id}/cancellation", this::cancelReservation);
        app.post("/reservations/{id}/check-in", this::checkIn);
        app.post("/reservations/{id}/check-out", this::checkOut);
        app.get("/reservations/{id}/document", this::getDocument);
    }

    private void createReservation(io.javalin.http.Context ctx) {
        try {
            JsonObject body = ctx.bodyAsClass(JsonObject.class);

            int roomNumber = getIntField(body, "roomNumber");
            String guestName = getStringField(body, "guestName");
            String guestEmail = getStringField(body, "guestEmail");
            String guestCpf = getStringField(body, "guestCpf");
            LocalDate checkIn = getDateField(body, "checkIn");
            LocalDate checkOut = getDateField(body, "checkOut");
            int guests = getIntField(body, "guests");
            RatePlan ratePlan = getRatePlanField(body, "ratePlan");
            String companyCode = getOptionalStringField(body, "companyCode");

            Reservation reservation = reservationService.createReservation(
                roomNumber, guestName, guestEmail, guestCpf,
                checkIn, checkOut, guests, ratePlan, companyCode
            );

            ctx.status(201);
            ctx.json(reservationToJson(reservation));
        } catch (ReservationException e) {
            sendErrorResponse(ctx, e.getStatusCode(), e.getErrorCode(), e.getMessage());
        } catch (Exception e) {
            sendErrorResponse(ctx, 400, "INVALID_REQUEST", e.getMessage());
        }
    }

    private void getReservation(io.javalin.http.Context ctx) {
        try {
            int id = ctx.pathParamAsClass("id", Integer.class).get();
            Reservation reservation = reservationService.getReservation(id);
            ctx.json(reservationToJson(reservation));
        } catch (ReservationException e) {
            sendErrorResponse(ctx, e.getStatusCode(), e.getErrorCode(), e.getMessage());
        }
    }

    private void confirmReservation(io.javalin.http.Context ctx) {
        try {
            int id = ctx.pathParamAsClass("id", Integer.class).get();
            JsonObject body = ctx.bodyAsClass(JsonObject.class);
            BigDecimal amountPaid = getBigDecimalField(body, "amountPaid");

            Reservation reservation = reservationService.confirmReservation(id, amountPaid);
            ctx.json(reservationToJson(reservation));
        } catch (ReservationException e) {
            sendErrorResponse(ctx, e.getStatusCode(), e.getErrorCode(), e.getMessage());
        } catch (Exception e) {
            sendErrorResponse(ctx, 400, "INVALID_REQUEST", e.getMessage());
        }
    }

    private void cancelReservation(io.javalin.http.Context ctx) {
        try {
            int id = ctx.pathParamAsClass("id", Integer.class).get();
            Reservation reservation = reservationService.cancelReservation(id);
            ctx.json(reservationToJson(reservation));
        } catch (ReservationException e) {
            sendErrorResponse(ctx, e.getStatusCode(), e.getErrorCode(), e.getMessage());
        }
    }

    private void checkIn(io.javalin.http.Context ctx) {
        try {
            int id = ctx.pathParamAsClass("id", Integer.class).get();
            Reservation reservation = reservationService.checkIn(id);
            ctx.json(reservationToJson(reservation));
        } catch (ReservationException e) {
            sendErrorResponse(ctx, e.getStatusCode(), e.getErrorCode(), e.getMessage());
        }
    }

    private void checkOut(io.javalin.http.Context ctx) {
        try {
            int id = ctx.pathParamAsClass("id", Integer.class).get();
            Reservation reservation = reservationService.checkOut(id);
            JsonObject receiptJson = receiptToJson(reservation);
            ctx.json(receiptJson);
        } catch (ReservationException e) {
            sendErrorResponse(ctx, e.getStatusCode(), e.getErrorCode(), e.getMessage());
        }
    }

    private void getDocument(io.javalin.http.Context ctx) {
        try {
            int id = ctx.pathParamAsClass("id", Integer.class).get();
            Reservation reservation = reservationService.getReservation(id);

            if (reservation.getAmountPaid().compareTo(java.math.BigDecimal.ZERO) == 0) {
                sendErrorResponse(ctx, 409, "OPERATION_NOT_ALLOWED", "Document only available for paid reservations");
                return;
            }

            JsonObject receiptJson = receiptToJson(reservation);
            ctx.json(receiptJson);
        } catch (ReservationException e) {
            sendErrorResponse(ctx, e.getStatusCode(), e.getErrorCode(), e.getMessage());
        }
    }

    private JsonObject reservationToJson(Reservation res) {
        JsonObject json = new JsonObject();
        json.addProperty("id", res.getId());
        json.addProperty("roomNumber", res.getRoomNumber());
        json.addProperty("guestName", res.getGuestName());
        json.addProperty("guestEmail", res.getGuestEmail());
        json.addProperty("guestCpf", res.getGuestCpf());
        json.addProperty("checkIn", res.getCheckIn().format(DATE_FORMATTER));
        json.addProperty("checkOut", res.getCheckOut().format(DATE_FORMATTER));
        json.addProperty("guests", res.getGuests());
        json.addProperty("ratePlan", res.getRatePlan().toString());
        json.addProperty("nights", res.getNights());
        json.addProperty("subtotal", res.getSubtotal().doubleValue());
        json.addProperty("discount", res.getDiscount().doubleValue());
        json.addProperty("total", res.getTotal().doubleValue());
        json.addProperty("status", res.getStatus().toString());
        json.addProperty("amountPaid", res.getAmountPaid().doubleValue());
        if (res.getRefund() != null) {
            json.addProperty("refund", res.getRefund().doubleValue());
        } else {
            json.add("refund", null);
        }
        return json;
    }

    private JsonObject receiptToJson(Reservation res) {
        JsonObject json = new JsonObject();
        json.addProperty("title", "Comprovante de reserva");
        json.addProperty("reservationId", res.getId());
        json.addProperty("guestName", res.getGuestName());
        json.addProperty("guestCpf", res.getGuestCpf());
        json.addProperty("roomNumber", res.getRoomNumber());
        json.addProperty("roomType", res.getRatePlan() == com.pousadamareaita.model.RatePlan.CORPORATE ?
            com.pousadamareaita.storage.RoomRepository.class.getClassLoader().getResource("") : "UNKNOWN");
        json.addProperty("checkIn", res.getCheckIn().format(DATE_FORMATTER));
        json.addProperty("checkOut", res.getCheckOut().format(DATE_FORMATTER));
        json.addProperty("nights", res.getNights());
        json.addProperty("subtotal", res.getSubtotal().doubleValue());
        json.addProperty("discount", res.getDiscount().doubleValue());
        json.addProperty("total", res.getTotal().doubleValue());
        return json;
    }

    private void sendErrorResponse(io.javalin.http.Context ctx, int status, String errorCode, String message) {
        ctx.status(status);
        JsonObject error = new JsonObject();
        error.addProperty("error", errorCode);
        error.addProperty("message", message);
        ctx.json(error);
    }

    private int getIntField(JsonObject obj, String field) {
        if (!obj.has(field)) {
            throw new IllegalArgumentException("Missing field: " + field);
        }
        return obj.get(field).getAsInt();
    }

    private String getStringField(JsonObject obj, String field) {
        if (!obj.has(field)) {
            throw new IllegalArgumentException("Missing field: " + field);
        }
        return obj.get(field).getAsString();
    }

    private String getOptionalStringField(JsonObject obj, String field) {
        if (!obj.has(field)) {
            return null;
        }
        JsonElement elem = obj.get(field);
        if (elem.isJsonNull()) {
            return null;
        }
        return elem.getAsString();
    }

    private BigDecimal getBigDecimalField(JsonObject obj, String field) {
        if (!obj.has(field)) {
            throw new IllegalArgumentException("Missing field: " + field);
        }
        return new BigDecimal(obj.get(field).getAsString());
    }

    private LocalDate getDateField(JsonObject obj, String field) {
        if (!obj.has(field)) {
            throw new IllegalArgumentException("Missing field: " + field);
        }
        try {
            return LocalDate.parse(obj.get(field).getAsString(), DATE_FORMATTER);
        } catch (Exception e) {
            throw new IllegalArgumentException("Invalid date format for " + field + ": " + e.getMessage());
        }
    }

    private RatePlan getRatePlanField(JsonObject obj, String field) {
        if (!obj.has(field)) {
            throw new IllegalArgumentException("Missing field: " + field);
        }
        try {
            return RatePlan.valueOf(obj.get(field).getAsString());
        } catch (Exception e) {
            throw new IllegalArgumentException("Invalid rate plan: " + e.getMessage());
        }
    }
}

