package com.pousadamareaita.http;

import com.pousadamareaita.storage.RoomRepository;
import io.javalin.Javalin;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.pousadamareaita.model.Room;

public class RoomController {
    private final RoomRepository roomRepository;

    public RoomController(RoomRepository roomRepository) {
        this.roomRepository = roomRepository;
    }

    public void registerRoutes(Javalin app) {
        app.get("/rooms", ctx -> {
            JsonArray rooms = new JsonArray();
            for (Room room : roomRepository.findAll()) {
                JsonObject roomJson = new JsonObject();
                roomJson.addProperty("number", room.getNumber());
                roomJson.addProperty("type", room.getType().toString());
                roomJson.addProperty("capacity", room.getCapacity());
                roomJson.addProperty("nightlyRate", room.getNightlyRate().doubleValue());
                rooms.add(roomJson);
            }
            ctx.json(rooms);
        });
    }
}

